+	describe('incrObjectFieldByBulk', () => {
+		before(async () => {
+			await db.setObject('testObject16', { age: 100 });
+		});
+
+		it('should increment multiple object fields', async () => {
+			await db.incrObjectFieldByBulk([
+				['testObject16', { age: 5, newField: 10 }],
+				['testObject17', { newField: -5 }],
+			]);
+			const d = await db.getObjects(['testObject16', 'testObject17']);
+			assert.equal(d[0].age, 105);
+			assert.equal(d[0].newField, 10);
+			assert.equal(d[1].newField, -5);
+		});
+
+		it('should be a no-op and return undefined if data is not an array', async () => {
+			const before = await db.getObject('testObject16');
+			assert.strictEqual(await db.incrObjectFieldByBulk(null), undefined);
+			assert.strictEqual(await db.incrObjectFieldByBulk(undefined), undefined);
+			assert.strictEqual(await db.incrObjectFieldByBulk('abc'), undefined);
+			const after = await db.getObject('testObject16');
+			assert.deepStrictEqual(after, before);
+		});
+
+		it('should be a no-op and return undefined for an empty array', async () => {
+			const before = await db.getObject('testObject16');
+			const result = await db.incrObjectFieldByBulk([]);
+			assert.strictEqual(result, undefined);
+			const after = await db.getObject('testObject16');
+			assert.deepStrictEqual(after, before);
+		});
+
+		it('should return undefined on a successful bulk increment', async () => {
+			const result = await db.incrObjectFieldByBulk([
+				['testObject16_ret', { counter: 1 }],
+			]);
+			assert.strictEqual(result, undefined);
+		});
+
+		it('should invalidate cache so subsequent reads reflect the updated values', async () => {
